initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_015_independent_answers.json').read_text())}
items=[]
def m(s):return r'\('+s+r'\)'
def add(q,stem,values,reasons,answer,solution,core,theories,concept,conditions,discipline='physics_wave',ambiguity='',citations=(),calc=False,figure=False,verdicts=None):
 r=by[q];assert len(values)==len(reasons)==5
 if verdicts is None:verdicts=['最適' if i==answer else '不適切' for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='原典の条件・数式・単位・全5肢を実画像確認。'+('原典の配置図又は5候補表を照合し、独自説明で位置と符号を区別。' if figure else '設問固有図なし。'),ambiguity=ambiguity,evidence=initial[q]['source_images_viewed'],core_concept=core,required_knowledge=core+'。'+solution,solution=solution,independent_answer=initial[q]['independent_answer'],answer_reason=solution,learning_points=core+'を暗記だけでなく、位相・幾何・符号と成立条件から導く。選択肢番号を類似年度へそのまま移さない。',theory_references=theories,discipline_id=discipline,concept_id=concept,classification_reason='原典全5肢と条件を確認。中心概念は'+core+'。'+('光の量子性と電子の物質波を区別する問題であり、レンズ等の古典光学から現代物理へ分類修正。' if discipline=='physics_modern' else '既存分野内で問う概念を明確化。'),calculation=str(calc).lower(),figure=str(figure).lower(),law='false',evaluation=dict(knowledge_novelty='1',reasoning_steps='3' if calc else '2',calculation_load='2' if calc else '0',figure_reading='2' if figure else '0',difficulty='2',difficulty_reason='物理専攻者に既知の理論だが、距離の時点、実像・虚像の符号、位相差と次数、候補表の配列を照合する必要がある。'),citations=list(citations),foundationality='high',transferability='high'))
def w(*x):return ['theory:wave:'+s for s in x]
def o(*x):return ['theory:optics:'+s for s in x]
for q in ['H23-REG-APPLIED-03','H25-REG-APPLIED-05']:
 add(q,'静止した観測者から遠ざかる音源の観測振動数を求める。',[str(v)+' Hz' for v in [430,435,440,445,450]],['後退で下がる方向は正しいが、計算値約434.9 Hzには435の方が近い。','波面間隔が広がるため約434.9 Hzとなり、この候補が最も近い。','運動による波長変化を無視した音源そのものの振動数。','遠ざかるときの変化を接近と取り違えた候補。','遠ざかる音源で観測周波数が増えることはない。'],2,m(r'f_{\rm obs}=f_s c/(c+u)=440\times340/344\simeq434.9')+' Hzで2。音源が1周期の間に遠ざかる距離を波長へ加える。観測者の移動による波面の通過速度の変化とは分ける。','媒質基準の音源運動によるドップラー効果',w('doppler'),'acoustic_doppler',{'音源':'440 Hz、観測者から4 m/sで遠ざかる。','音速':'340 m/s。観測者は静止。','方向':'観測振動数に最も近い値。'},citations=['os_doppler'],calc=True)
lv=['外側／虚像／同じ／遠い／実像','外側／実像／反対／近い／虚像','内側／虚像／反対／遠い／実像','内側／実像／同じ／遠い／虚像','焦点上／実像／反対／近い／虚像']
lr=['焦点外の像を虚像とした点と正立とした点が誤り。内側では実像ではない。','焦点外は倒立実像で、物体を焦点へ近づけると像は遠ざかる。内側は正立虚像であり、全空欄が整合。','実像形成の対象位置と虚像の向きを取り違え、内側の像を実像としている。','焦点内の像は正立だが虚像である。最初の実像条件と像の向き、最後の実像が不整合。','物体が焦点上なら出射光は平行で、有限位置へ像はできない。最初の空欄が成立しない。']
for q in ['H23-REG-APPLIED-07','H26-REG-APPLIED-07']:
 add(q,'凸レンズの物体位置、像の実虚と向き、物体移動と像距離の変化を表の5空欄へ対応させる。',lv,lr,2,m(r'b=fa/(a-f)')+'より、a>fならb>0の倒立実像で、'+m(r'db/da=-f^2/(a-f)^2<0')+'なので物体がレンズに近付くと実像は遠ざかる。0<a<fならb<0、倍率−b/a>0の正立虚像である。5空欄が一致するのは2。','薄レンズの符号と像距離の単調性',o('lens'),'thin_lens',{'候補表':'各行はア・イ・ウ・エ・オの順。','条件':'凸レンズ、焦点距離の内外と有限の物体位置。','方向':'表の適切な組合せ。'},discipline='physics_optics',citations=['os_lens'],figure=True)
add('H24-REG-APPLIED-02','音の伝播、温度依存、流体の振動方向と固体の波速を判定する。',['真空中では音は伝わらない。','空気の温度が高いほど音速は大きい。','流体中を伝わる音は縦波である。','海水中の音速は空気中より小さい。','一般に固体中の縦波は横波より速い。'],['音は媒質の圧縮・変位の伝播であり、真空にはその媒質がない。','理想気体の'+m(r'c=\sqrt{\gamma RT/M}')+'では絶対温度の平方根に比例する。組成等を同じとして比較する。','静的せん断弾性を持たない流体では、通常の体積音波は圧縮の縦波となる。表面波とは区別。','海水では概ね1500 m/s、空気では概ね340 m/sであり比較方向が逆。状態により変わるがこの大小は通常逆転しない。','安定な等方線形弾性体で'+m(r'c_P^2-c_S^2=(K+\mu/3)/\rho>0')+'である。異方性媒質の全方向をこの式だけで扱わない。'],4,'媒質の体積弾性と密度が音速を決める。海水中の代表的な値は空気中より大きく、4が不適切。他の肢は通常の流体音波又は等方弾性体の一般的な説明として適切である。','圧縮波・せん断波の復元力と波速',w('elastic'),'acoustic_propagation',{'方向':'最も不適切。','範囲':'通常の音波。固体の比較は一般的な等方弾性体。'},citations=['os_sound'],verdicts=['適切','適切','適切','不適切','適切（一般的モデル）'])
sv=['赤外線→可視光線→紫外線→γ線','紫外線→可視光線→赤外線→γ線','赤外線→γ線→紫外線→可視光線','γ線→紫外線→可視光線→赤外線','γ線→赤外線→紫外線→可視光線']
for q,ans,direction in [('H24-REG-APPLIED-03',1,'波長の長い順'),('R02-REG-APPLIED-07',4,'光子エネルギーの大きい順')]:
 order='赤外→可視→紫外→γ' if ans==1 else 'γ→紫外→可視→赤外'
 reasons=['指定した順序は'+order+'であり、この候補は'+('整合する。' if i==ans else '少なくとも隣接2領域の大小関係が逆又は途中に不適切な領域を挟む。') for i in range(1,6)]
 add(q,'赤外・可視・紫外・γ線の4領域を'+direction+'に並べる。',sv,reasons,ans,m(r'c=f\lambda,\quad E=hf=hc/\lambda')+'より波長と光子エネルギーは逆順となる。'+direction+'は'+order+'で'+str(ans)+'。γ線を周波数の小さい領域として扱わない。','電磁波の波長・周波数・光子エネルギーの対応',o('spectrum'),'em_spectrum',{'方向':direction+'。','対象':'4つの電磁波領域。光子エネルギーを波の総エネルギーと区別。'},discipline='physics_optics',citations=['os_spectrum'])
add('H24-REG-APPLIED-07','光の粒子性に直接関係しない現象又は概念を選ぶ。',['光電効果','電子線回折','コンプトン効果','仕事関数','プランク定数'],['光がエネルギーhf単位で電子へ渡すモデルで、閾値周波数と光電子の最大運動エネルギーを説明する。','電子の物質波が結晶で干渉・回折する現象で、光の粒子性を直接示すものではない。','光子のエネルギー・運動量を電子との散乱で保存させ、波長変化を説明する。','表面から電子を取り出す最小エネルギーで、光電効果のエネルギー収支へ入る。これ自体を光子と同一の概念にはしない。','光子エネルギーhfや運動量h/λを結ぶ定数で、光の量子性へ直接関係する。'],2,'光子のエネルギーと運動量に関する1・3・4・5に対し、2は電子の波動性を観測する現象である。光の粒子性と物質粒子の波動性を区別して2を選ぶ。','光子の粒子性と電子の物質波', ['theory:modern:duality'],'photon_matter_wave',{'方向':'光の粒子性に直接関係しないことがらとして最適。'},discipline='physics_modern',citations=['os_photoelectric','os_matter'],verdicts=['直接関係','直接関係しない','直接関係','光電効果へ関係','直接関係'])
v1=[m(r'\lambda=2\pi/\omega,\ v=2\pi\omega/k'),m(r'\lambda=2\pi/\omega,\ v=2\pi k/\omega'),m(r'\lambda=2\pi/k,\ v=\omega/k'),m(r'\lambda=2\pi/k,\ v=k/\omega'),m(r'\lambda=2\pi/k,\ v=2\pi\omega/k')]
r1=['波長の分母は波数であり、角振動数ではない。速度に余分な2πもある。','波長は角振動数の逆数ではない。速度は逆数に加えて2πが余分。','空間位相が2π増える距離と位相一定の移動から導かれ、両方正しい。','k/ωは速度の逆数となり、速度の次元が違う。','波長は正しいが位相速度に余分な2πを掛けている。']
for q,order,ans in [('H25-REG-APPLIED-02',[0,1,2,3,4],3),('H29-REG-APPLIED-04',[0,1,4,3,2],5)]:
 add(q,'正弦進行波の位相から波長と位相速度の組合せを選ぶ。',[v1[i] for i in order],[r1[i] for i in order],ans,'空間で同位相が繰り返す条件は'+m(r'k\lambda=2\pi')+'。一定位相を微分すると'+m(r'\omega\,dt-k\,dx=0')+'で'+m(r'v=dx/dt=\omega/k')+'。両式が一致する'+str(ans)+'を選ぶ。角振動数と周期を取り違えない。','進行波の位相・波数・角振動数',w('phase'),'wave_kinematics',{'波':m(r'y=A\sin(\omega t-kx)')+'、A・ω・kは正。','方向':'波長λと伝播速度vの適切な組合せ。'},calc=True)
add('H27-REG-APPLIED-03','複スリットによる干渉縞の間隔を広げる変更を選ぶ。',['スリット間隔dを狭くする。','スリットの本数Nを増やす。','スクリーンまでの距離Lを短くする。','入射光の強度Iを強くする。','単色光の波長λを短くする。'],['主極大間隔Lλ/dはdを小さくすると広がる。','本数は主極大を狭く強くし、その間に副極大・暗線を増やすが、主極大同士の角間隔は変えない。','Lを短くするとスクリーン上の主極大間隔は狭くなる。','線形領域では強度は明るさを変え、位相の極大位置を変えない。','波長を短くすると主極大間隔は狭くなる。'],1,m(r'd\sin\theta=m\lambda')+'、遠方・小角で'+m(r'\Delta x\simeq L\lambda/d')+'より1。原典の「明線（もしくは暗線）」を複スリットの全ての暗線の個数まで含めた一様な間隔と読むと本数Nの影響もあり、主極大同士の間隔との区別を残す。','干渉主極大の位置と複スリット本数の役割',o('grating'),'optical_diffraction',{'配置':'スリット間隔d、本数N、強度I、波長λ、スクリーン距離L。','方向':'明線（もしくは暗線）の相互間隔を広げる変更。'},discipline='physics_optics',ambiguity='公式・独立解答1一致。複スリットN>2では主極大間に副極大・N−1個の暗線があり、全暗線の隣接間隔を主極大間隔と同一にできない。原典の括弧書きの範囲をAstraで確認。',citations=['os_grating','os_double'])
add('H28-REG-APPLIED-05','2枚の凸レンズの中間虚像を次の物体として、第二レンズの焦点距離を求める。',[str(v)+' cm' for v in [9,18,20,21,26]],['30 cmと60 cmに対し1/f=1/30+1/60が成立しない。','中間像を第一レンズ後方にある実像とみなすと物体距離を誤る。正しい値20 cmとは一致しない。','第二レンズから見た物体距離30 cm、実像60 cmを満たす。','正しい物体・像距離をレンズ式へ入れた20 cmと一致しない。','第一レンズの物体距離6 cmをそのまま第二レンズへ使う等の距離基準の混同ではないか確認する。正しい20 cmとは一致しない。'],3,'第一レンズは'+m(r'1/15=1/6+1/b_1')+'より'+m(r'b_1=-10')+' cmの虚像。第二レンズは第一より20 cm右なので、この像は第二から30 cm左の実物体となる。最終像60 cmを使い'+m(r'f_2=(1/30+1/60)^{-1}=20')+' cmで3。','2枚の薄レンズと中間像の符号・距離基準',o('lens','cascade'),'thin_lens',{'第一レンズ':'焦点距離15 cm、物体は手前6 cm。','第二レンズ':'第一より20 cm後方、最終像は第二より後方60 cm。','方向':'第二レンズの焦点距離。'},discipline='physics_optics',citations=['os_lens'],calc=True,figure=True)
add('H30-REG-APPLIED-05','岸壁へ接近する船が汽笛の反射音を聞いた時点の岸壁までの距離を求める。',[str(v)+' m' for v in [450,480,510,540,570]],['船の移動60 mを正しい往復の幾何から減じた480 mとは一致しない。','発音時540 mから移動60 mを差し引いた到着時距離。','静止する船としてct/2を計算した値で、船の移動を無視している。','発音時の距離であり、反射音を聞いた時点の距離ではない。','移動方向が接近であることと、音の往復距離の減少を正しく反映していない。'],2,'発音時の距離をD0、戻るまでt=3 sとすると音の総行程は'+m(r'ct=D_0+(D_0-ut)')+'。'+m(r'D_0=(c+u)t/2=540')+' m、戻った時点では'+m(r'D_1=D_0-ut=480')+' mとなり2。','移動する観測位置と反射音の往復幾何',w('echo'),'acoustic_doppler',{'船速':'岸壁へ20 m/sで等速接近。','音速・時間':'340 m/s、汽笛から反射音到着まで3 s。','問う時点':'反射音を聞いた時点。'},calc=True)
for q,a,L,values,ans in [('R01-REG-APPLIED-05',2,3.3,[280,310,370,430,490],2),('R05-REG-APPLIED-05',2.4,4.0,[160,210,260,320,400],3)]:
 import math
 delta=math.sqrt(L*L+a*a)-L;f=340/(2*delta)
 reasons=[('道のり差約'+format(delta,'.4f')+' mが半波長となる振動数約'+format(f,'.1f')+' Hzに最も近い。' if i==ans else '最初の逆位相による極小の振動数約'+format(f,'.1f')+' Hzから、正答候補より離れている。次の奇数次数は候補範囲外。') for i in range(1,6)]
 add(q,'2スピーカの正面での強め合いと、片方の正面での極小から音の振動数を求める。',[str(v)+' Hz' for v in values],reasons,ans,'中央では両経路が等しく強め合う。片方の正面では距離'+m('L')+'と'+m(r'\sqrt{L^2+a^2}')+'の差'+m(r'\Delta=\sqrt{L^2+a^2}-L')+'がある。逆位相の条件'+m(r'\Delta=(2n+1)\lambda/2')+'の最初n=0では'+m(r'f=c/(2\Delta)')+'≈'+format(f,'.1f')+' Hzで'+str(ans)+'。次のn=1は約'+format(3*f,'.1f')+' Hzで全候補より大きい。原典に最初の極小とは明示されないが、候補の範囲で次数を確認できる。距離差により振幅が異なるなら極小は必ずしも無音ではない。','幾何学的経路差とコヒーレントな音の位相差',w('interference'),'acoustic_interference',{'配置':'スピーカ間隔'+str(a)+' m、正面の聴取線まで'+str(L)+' m。','観測':'中央は強め合い、片方の正面で最小。音速340 m/s。','次数':'初回極小という明示なし。候補範囲も照合。'},citations=['os_superposition'],calc=True,figure=True)
add('R01-RET-APPLIED-03','反射位相、ニュートンリング、スリット、色収差、光ファイバの屈折率を判定する。',['空気中のガラスの表面反射は位相反転し、裏面での内部反射は反転しない。','ニュートンリング半径は照射波長が長いほど大きい。','2スリットの間隔を狭くすると遠方の干渉縞間隔は広がる。','凸レンズの平行光の焦点は紫より赤が遠い。','光ファイバはクラッドの屈折率をコアより大きくして全反射を利用する。'],['損失のない通常の誘電体のほぼ垂直な入射では、低屈折率から高屈折率の反射でπ反転し、逆方向では反転しない。原典に入射角指定はなく、全斜入射・偏光まで同じとする規則へ拡張しない。','同じ曲率半径・次数で半径の二乗が波長に比例する。反射明環と暗環の定数は違うが大小の方向は一致。','遠方・小角でLλ/dであるから、dの減少で間隔が増える。','通常の分散では紫の屈折率が赤より大きく、同じ形状の凸レンズの焦点距離は紫が短い。異常分散を無制限に排除する一般則ではない。','全反射には高屈折率側から低屈折率側への入射が必要。コアの方が高く、記述が逆。'],5,'コアからクラッドへの全反射条件は'+m(r'n_{\rm core}>n_{\rm clad}')+'である。逆にした5が不適切。その他は通常の透明誘電体・近軸・正常分散という基礎光学モデルの範囲で適切であり、未指定の角度を問題の所与条件として追加しない。','屈折率の大小と位相・全反射・色収差',o('reflection','newton','grating','refraction'),'optical_diffraction',{'方向':'最も不適切。','範囲':'透明ガラス・単色干渉・通常の凸レンズ・光ファイバ。入射角等の細かな指定なし。'},discipline='physics_optics',citations=['os_fiber','os_thinfilm','os_lens'],verdicts=['適切（通常のモデル）','適切','適切','適切（正常分散）','不適切'])
add('R02-REG-APPLIED-05','単色光の第一回折明線の角度から回折格子1 mm当たりの本数を求める。',[str(v)+' 本/mm' for v in [33,65,130,390,770]],['格子間隔の逆数と第一次数の条件を満たさず、正しい約769本/mmから遠い。','nmからmmへの変換と、間隔の逆数を確認する。正しい本数とは一桁以上違う。','間隔1300 nmを単なる整数の本数へ読み替えていないか確認する。正しい約769本/mmではない。','sin30°の因子を逆に扱う等の誤りで、本数がほぼ半分になっている。','d=1.3 µmに対して1 mm/d≈769本/mmで最も近い。'],5,m(r'd\sin30^\circ=650\ {\rm nm}')+'からd=1300 nm=0.0013 mm。したがって'+m(r'1/d\simeq769.2')+' 本/mmとなり5。格子間隔と本数を同じ量としない。','回折格子の光路差と格子定数の逆数',o('grating'),'optical_diffraction',{'光':'格子へ垂直に入射、波長650 nm。','回折':'第一明線30度。','方向':'1 mm当たりの格子本数に最も近い値。'},discipline='physics_optics',citations=['os_grating'],calc=True)
add('R03-REG-APPLIED-05','空気層の反射ニュートンリングで明環半径と曲率半径・波長・次数を対応させる。',[m(r'2x^2/R=m\lambda'),m(r'2x^2/R=(m+1/2)\lambda'),m(r'x^2/R=(m+1/2)\lambda'),m(r'x^2/R=m\lambda'),m(r'x^2/(2R)=(m+1/2)\lambda')],['曲面の幾何による往復空気層の厚さはx²/Rで、2x²/Rではない。整数倍も反射明環に対応しない。','半整数は反射明環の条件だが、幾何の係数が2倍。','mを0,1,2,…とする干渉次数なら正しい。ただし原典のm番目の数え始めは明示されない。','片方の反射のみ位相反転するため、整数倍は反射暗環の条件となる。','x²/(2R)は片道の厚さtであり、明環の位相条件には往復2tを使う。'],3,'球面の幾何から'+m(r't=R-\sqrt{R^2-x^2}\simeq x^2/(2R)')+'。空気層の一方の反射にπの相対位相があるため反射明環は'+m(r'2t=(n+1/2)\lambda')+'、n=0,1,…で、式は3に対応する。原典の「m番目」を1からの序数と読むなら'+m(r'x^2/R=(m-1/2)\lambda')+'となり、該当肢がない。公式3を保持し、次数記号の解釈を確定済みとしない。','反射位相・空気層の厚さ・明環の次数定義',o('newton','reflection'),'thinfilm_interference',{'配置':'曲率半径Rの平凸レンズを凸面下に平面ガラスへ置く。接点Oから距離x。','光':'上から垂直な単色光、波長λ。反射で同心円状の縞を観察。','方向':'原文はOからm番目の明環。次数の開始値は明示なし。'},discipline='physics_optics',ambiguity='独立3・公式3一致。ただし3はm=0始まりの干渉次数で成立。m番目を1始まりの序数と読むならm−1/2が必要で候補なし。開始値を原典所与として補わず部分校正。Astraで反射/透過と位相反転も確認。',citations=['os_thinfilm'],calc=True)
add('R04-REG-APPLIED-05','リサジュー図形、波の振動方向、衝撃波、縦横波の速さ、AMを判定する。',['垂直な単振動の合成軌道は一般にリサジュー図形という。','伝播方向と媒質の振動方向が一致する波を横波という。','衝撃波は媒質中を超音速で伝播する圧縮波である。','一般に固体中の縦波は横波より速い。','AMは信号に応じて搬送波の振幅を変える方式である。'],['xとyの単振動の周波数比・位相差で軌道が変わる。比が有理なら閉曲線となる。','一致する波は縦波である。横波は伝播に垂直な振動を持つ。','不連続な圧力等の変化を伴う圧縮の前面が、未擾乱側の小振幅音速を超えて進む。小振幅正弦波とは分ける。','安定な等方線形弾性体では縦波の復元力はK+4µ/3、横波はµなので、密度が同じなら縦波が速い。','振幅包絡へ信号を入れる方式で、周波数を変えるFMと異なる。'],2,'縦波・横波は速さではなく、変位方向と伝播方向の関係で定義する。同方向を横波とした2が不適切。固体の波速の一般的な比較は等方弾性体モデルで確認する。','波の偏り、非線形な圧縮波、変調と単振動合成',w('elastic','applications'),'acoustic_propagation',{'方向':'最も不適切。','範囲':'振動・波動の一般的説明。'},citations=['os_sound'],verdicts=['適切','不適切','適切','適切（一般的モデル）','適切'])
add('R06-REG-APPLIED-05','焦点内の物体を凸レンズで見たときの像の位置・向き・実虚を求める。',['手前15 cmに正立虚像。','手前15 cmに倒立実像。','後方6 cmに倒立虚像。','後方30 cmに倒立実像。','手前30 cmに正立虚像。'],['正立虚像という性質は合うが、像距離の大きさは30 cm。','像の距離、倒立、実像の全てが焦点内物体の像と異なる。','光線の延長は物体側へ交わるので、位置・向き・6 cmの距離が不整合。','30 cmという大きさのみ合い、物体側という位置と正立虚像という性質が逆。','b=-30 cm、倍率−b/a=3なので物体側30 cmの正立虚像。'],5,m(r'1/15=1/10+1/b')+'よりb=−30 cm。像は入射側にあり、倍率'+m(r'M=-b/a=3>0')+'なので正立虚像で5。負の像距離を負の物理的長さとせず、位置の符号として読む。','薄レンズ焦点内の正立虚像と符号',o('lens'),'thin_lens',{'レンズ':'焦点距離15 cmの凸レンズ。','物体':'レンズ手前10 cm。','方向':'像位置と実虚・向きの組合せ。'},discipline='physics_optics',citations=['os_lens'],calc=True)
add('R07-REG-APPLIED-05','周期Tと波長λで書かれた正弦波の位相速度と角振動数を求める。',[m(r'v=2\pi/\lambda,\ \omega=\lambda/T'),m(r'v=\lambda T,\ \omega=2\pi/\lambda'),m(r'v=2\pi\lambda/T,\ \omega=2\pi/T'),m(r'v=\lambda/T,\ \omega=2\pi/T'),m(r'v=\lambda/T,\ \omega=2\pi\lambda T')],['速度と角振動数の双方の次元が異なる。','速度は周期で割る量であり積ではない。角振動数も空間の波数ではない。','角振動数は正しいが、位相速度に余分な2πがある。','位相一定の微分と時間位相係数を両方満たす。','速度は正しいが角振動数に波長と周期を掛け、次元が異なる。'],4,m(r'y=A\sin\{2\pi(t/T-x/\lambda)\}')+'の時間係数は'+m(r'\omega=2\pi/T')+'。一定位相では'+m(r'dt/T=dx/\lambda')+'なので'+m(r'v=\lambda/T')+'で4。','周期・波長による位相速度と角振動数',w('phase'),'wave_kinematics',{'波':m(r'y=A\sin\{2\pi(t/T-x/\lambda)\}')+'。A,T,λは正。','方向':'伝播速度vと角振動数ωの適切な組合せ。','候補5':'角振動数は2πλT（原画像照合、OCR誤認を採用しない）。'},calc=True)
